package reviewpub

import "strings"

// hostFooters is the closed list of footer lines a managed sandbox host is
// known to append to every comment it posts (for example a hosted agent
// session's "Generated by" attribution). The list is data: recognising another
// host is one entry here and one row in the predicate tables, never a heuristic
// such as "any trailing italic line".
var hostFooters = []string{
	"_Generated by [Claude Code](https://claude.ai/code)_",
}

// HostFooters returns the recognised host footer lines. The blind publication
// helper keeps its own copy of this list for its read-back confirmation; a
// parity test pins the two together.
func HostFooters() []string {
	return append([]string(nil), hostFooters...)
}

// TrimHostSuffix removes exactly one host-appended trailing block from body and
// reports whether it found one. The block is a recognised footer line directly
// preceded by a "---" separator line, which is itself preceded by at least one
// blank line, and it must be the last thing in the body once trailing blank
// lines are ignored. A separator that follows text without a blank line is a
// Markdown heading underline, not a block, and a block that is not last (text
// after it, or a second block) is not recognised either.
//
// The returned prefix is exactly what the strict publication predicates judge:
// trailing blank lines are dropped and a trailing "\r" is stripped from its
// lines, so a host that also converted line endings still leaves identity and
// verdict lines the strict matchers accept. Only one block is ever removed, so
// a second block leaves a footer as the last line and the strict identity check
// rejects it. When no block is recognised, body is returned unchanged.
//
// The remainder is not required to be a publication: judging that, and binding
// it to a head, stays with the strict predicates. That is also why a suffix can
// never carry a verdict or an identity of its own.
func TrimHostSuffix(body string) (string, bool) {
	lines := strings.Split(body, "\n")
	end := len(lines)
	for end > 0 && strings.TrimSpace(lines[end-1]) == "" {
		end--
	}
	// A block spans a footer line, a separator line and one blank line.
	if end < 3 ||
		!isHostFooter(strings.TrimSpace(lines[end-1])) ||
		strings.TrimSpace(lines[end-2]) != "---" ||
		strings.TrimSpace(lines[end-3]) != "" {
		return body, false
	}
	prefix := lines[:end-3]
	for len(prefix) > 0 && strings.TrimSpace(prefix[len(prefix)-1]) == "" {
		prefix = prefix[:len(prefix)-1]
	}
	if len(prefix) == 0 {
		return "", true
	}
	kept := make([]string, len(prefix))
	for i, line := range prefix {
		kept[i] = strings.TrimRight(line, "\r")
	}
	return strings.Join(kept, "\n") + "\n", true
}

func isHostFooter(line string) bool {
	for _, footer := range hostFooters {
		if line == footer {
			return true
		}
	}
	return false
}
